#include <string_view>

#include "cinux/result.hpp"

using namespace cinux::base;

void ErrorStringExample() {
    // 表长和枚举项在编译期就对上了，问不存在的项拿到 "Unknown"
    static_assert(std::string_view(ErrorString(KernelError::kNotFound)) == "NotFound");

    const char* kName = ErrorString(KernelError::kConnectionReset);
    // kName == "ConnectionReset" · 连接被对端重置
}

cinux::base::Result::ok.example:
#include "cinux/result.hpp"

using namespace cinux::base;

void ResultOkExample() {
    const Result<int> kValue(42);  // 成功路径，存一个 int
    const bool kHaveValue = kValue.ok();
    // kHaveValue == true

    const Result<int> kFailure(KernelError::kNotFound);  // 错误路径，只存错误码
    const bool kFailureOk = kFailure.ok();
    // kFailureOk == false

    const int kNumber = kHaveValue ? kValue.value() : -1;
    // kNumber == 42 · 先用 ok() 问过再取，没问就取会走断言终止
}

cinux::base::Result< void, ErrorType >::.example:
#include "cinux/result.hpp"

using namespace cinux::base;

void VoidResultErrorExample() {
    constexpr Result<void> kSuccess{};  // 默认构造，表示成功
    static_assert(kSuccess.error() == KernelError::kOk);

    constexpr Result<void> kFailure(KernelError::kOutOfMemory);  // 错误路径只带一个码
    static_assert(kFailure.error() == KernelError::kOutOfMemory);
}
